INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('72e6d5c9-7b19-be2b-84f3-9d371d881856', 'Orient Bambino Multi-Function Grey Dial Automatic', 'orient-bambino-multi-function-grey-dial', 'Orient Bambino Multi-Function — o''zgacha kulrang (antratsit) siferblatli va zaytun rangli charm tasmali yapon soati. Hafta kuni sub-diali, 24 soatlik vaqt indikatori, Rim raqamlari va soat 3 da sana darchasi. Yaponiyaning afsonaviy Orient avtomatik mexanizmi va gumbazsimon mineral shisha. 2 yil rasmiy kafolat bilan.', 3300000, 3800000, 13, '118dee4b-db4d-e74d-7eeb-2264e986b373', 'Orient', 5, 'ORT-BAMBINO-MF-GRY', 5, 6, '/products/orient_bambino_grey_dial.png', true, false, true, '{"Korpus o''lchami":"40.5 mm","Korpus materiali":"Zanglamas po''lat 316L","Mexanizm":"Orient Cal. Avtomatik (Yaponiya)","Shisha turi":"Gumbazsimon mineral kristall","Tasma":"Tabiiy zaytun-kulrang charm (Alligator naqshli)","Funksiyalar":"Hafta kuni sub-diali, 24 soatlik indikator, Sana","Suvga chidamlilik":"30 metr / 3 BAR","Kafolat":"2 yil rasmiy kafolat"}'::jsonb) ON CONFLICT (id) DO NOTHING;
