INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('6243641c-20c9-b71a-c305-f396ea6a0004', 'Tissot Gentleman Powermatic 80 Open Heart 🇨🇭', 'tissot-gentleman-powermatic-80-open-heart', 'Original Shveytsariya brendi Tissot''dan afsonaviy Gentleman Powermatic 80 Open Heart modeli. 80 soatlik quvvat zaxirasiga ega Shveytsariya avtomatik mexanizmi (Powermatic 80) va antimagnit Nivachron prujinasi. Soat 12 da ochiq mexanizm yurishi (Open Heart), qirilmaydigan antirefleksli sapfir kristall shisha, pushti tilla PVD indekslar va yaltiroq po''lat korpus. 100 metr (10 ATM) suvga chidamlilik. Narxi: $900 (11 500 000 so''m). Original qutisi va xalqaro sertifikati bilan.', 11500000, 13000000, 12, '5d0c6b4d-072b-e8cc-e434-809c655695be', 'Tissot', 3, 'TIS-GENTLEMAN-PM80-OH', 5, 12, '/products/tissot_gentleman_powermatic_80_open_heart.png', true, false, true, '{"Ishlab chiqaruvchi davlat":"Shveytsariya (Swiss Made 🇨🇭)","Korpus o''lchami":"40 mm","Korpus va braslet":"316L zanglamas tibbiy po''lat (Solid Stainless Steel)","Mexanizm":"Swiss Powermatic 80.601 Avtomatik (80 soat quvvat zaxirasi)","Xususiyat":"Open Heart (Ochiq balans), Nivachron antimagnit prujina","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Suvga chidamlilik":"10 ATM / 100 metr","Komplektatsiya":"Original hashamatli Tissot qutisi, hujjatlar, xalqaro kafolat kartasi","Kafolat":"2 yil xalqaro rasmiy kafolat","Valyuta narxi":"$900"}'::jsonb) ON CONFLICT (id) DO NOTHING;
