INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('ac6667e0-3fc4-936f-44fd-141a454351ed', 'Orient Sun & Moon Contemporary Limited Edition Sapphire Automatic', 'orient-sun-moon-contemporary-sapphire-automatic', 'Original Orient Sun & Moon Contemporary Limited Edition — yapon nozik soatsozlik san''atining oliy namunasi. Qirilishga qarshi sapfir kristall shisha (Sapphire Crystal), to''liq zanglamas 316L po''lat korpus va braslet. Soat 5 da quyosh va oy fazalari indikatori (Sun & Moon), soat 10 da hafta kuni retrograd sub-diali, soat 3 da sana darchasi va jozibali qizil soniya strelkasi. Orient avtomatik mexanizmi. Komplektda: original quti, Timeless rasmiy kafolat kartasi va hujjatlar bilan. Narxi: $400.', 5120000, 5800000, 12, '118dee4b-db4d-e74d-7eeb-2264e986b373', 'Orient', 4, 'ORT-SUN-MOON-CONT-SAP', 5, 11, '/products/orient_sun_moon_contemporary_sapphire.png', true, false, true, '{"Korpus o''lchami":"40 mm","Korpus va braslet":"Zanglamas po''lat 316L (Solid Stainless Steel)","Mexanizm":"Orient Cal. F6B24 Avtomatik (Yaponiya)","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Funksiyalar":"Sun & Moon (Kun/Tun animatsiyasi), Retrograd hafta kuni, Sana","Suvga chidamlilik":"50 metr / 5 BAR","Komplektatsiya":"Original Orient qutisi, Timeless firma paketi, kafolat kartasi va hujjatlar","Kafolat":"2 yil rasmiy kafolat (Timeless)","Valyuta narxi":"$400"}'::jsonb) ON CONFLICT (id) DO NOTHING;
