INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('8556f51e-8309-cd93-d892-427c14ce83a6', 'Orient Bambino Rose Gold Classic Automatic', 'orient-bambino-rose-gold-classic-automatic', 'Orient Bambino Rose Gold — nozik pushti tilla (Rose Gold PVD) qoplamali nafis korpus va shaffof oq siferblatli yapon klassik avtomatik soati. O''tkir fasetlangan qirrali tilla indekslar, dauphine strelkalar, soat 3 da sana darchasi va to''q jigarrang tabiiy charm tasma. Sapfir kristall shisha va ishonchli yapon avtomatik mexanizmi. Original qutisi, hujjatlari va 2 yil rasmiy kafolat bilan.', 3000000, 3450000, 13, '118dee4b-db4d-e74d-7eeb-2264e986b373', 'Orient', 5, 'ORT-BAMBINO-RG-WHT', 5, 8, '/products/orient_bambino_rose_gold_white_dial.png', true, false, true, '{"Korpus o''lchami":"40 mm","Korpus materiali":"Rose Gold PVD qoplamali zanglamas po''lat 316L","Mexanizm":"Orient Cal. F6724 Avtomatik (Yaponiya)","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Tasma":"Tabiiy to''q jigarrang charm (Alligator naqshli)","Funksiyalar":"Sana darchasi, Qo''lda burash & Hacking","Suvga chidamlilik":"30 metr / 3 BAR","Komplektatsiya":"Original Orient qutisi, hujjatlar, kafolat taloni","Kafolat":"Mexanizmiga 2 yil rasmiy kafolat"}'::jsonb) ON CONFLICT (id) DO NOTHING;
