INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('9f51da71-b78d-db33-dcaf-76a713fd6c8d', 'Tissot Bellissima Small Lady Sapphire 26mm 🇨🇭', 'tissot-bellissima-small-lady-sapphire-26mm', 'Original Shveytsariya brendi Tissot''dan nafis ayollar to''plami — Tissot Bellissima Small Lady. 26 mm ixcham nozik korpus, Rim raqamli klassik guilloché siferblat, siferblat markazida sanasi va tojida ko''k kaboshon toshi. Qirilmaydigan sapfir kristall shisha (Sapphire Crystal), 316L zanglamas po''lat va pushti tilla bi-color variantlari. 50 metr (5 ATM) suvga chidamlilik. To''plamda: original Tissot qutisi, hujjatlar va xalqaro kafolat kartasi. Narxi: $350 - $390.', 4480000, 5100000, 12, '63e89563-ed97-e3dd-90e2-8fb4d29f36e7', 'Tissot', 6, 'TIS-BELLISSIMA-26-LADY', 5, 14, '/products/tissot_bellissima_swiss_ladies.png', true, false, true, '{"Ishlab chiqaruvchi davlat":"Shveytsariya (Swiss Made 🇨🇭)","Korpus o''lchami":"26 mm (Nafis ayollar o''lchami)","Korpus va braslet":"316L zanglamas po''lat (Steel & Bi-color Rose Gold)","Mexanizm":"Swiss Made ETA Yuqori aniqlikdagi mexanizm (Yaponiya/Shveytsariya)","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Funksiyalar":"Rim raqamlari, Sana darchasi, Ko''k kaboshon toshli toj","Suvga chidamlilik":"50 metr / 5 BAR","Komplektatsiya":"Original hashamatli Tissot qutisi, hujjatlar, xalqaro kafolat taloni","Kafolat":"2 yil xalqaro rasmiy kafolat","Valyuta narxi":"$350 - $390"}'::jsonb) ON CONFLICT (id) DO NOTHING;
