INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('3e4b57cd-99d0-8b4b-a5c0-0fe269e42bb0', 'Tissot Ballade Fluted Bezel Bi-Color Sapphire 40mm 🇨🇭', 'tissot-ballade-fluted-bezel-bicolor-sapphire-40mm', 'Original Shveytsariya brendi Tissot''dan hashamatli Ballade modeli. Elegant qirrali oltin lyunet (Fluted Bezel), quyosh nurlari taratuvchi guilloché siferblat va 5 qatorli Jubilee uslubidagi bi-color (po''lat & oltin PVD) braslet. Qirilmaydigan sapfir kristall shisha (Sapphire Crystal), soat 3 da sana darchasi. 40 mm klassik korpus. Komplektda: original Tissot qutisi, hujjatlar va 2 yil xalqaro rasmiy kafolat bilan. Narxi: $350.', 4480000, 5100000, 12, '5d0c6b4d-072b-e8cc-e434-809c655695be', 'Tissot', 5, 'TIS-BALLADE-FLUTED-40', 5, 15, '/products/tissot_ballade_fluted_bezel_bicolor.jpg', true, false, true, '{"Ishlab chiqaruvchi davlat":"Shveytsariya (Swiss Made 🇨🇭)","Korpus o''lchami":"40 mm","Bezel (Lyunet)":"Qirrali oltin lyunet (Fluted Bezel — nufuzli dizayn)","Korpus va braslet":"316L zanglamas po''lat va sariq oltin PVD (Jubilee bi-color)","Mexanizm":"Swiss Made ETA Yuqori aniqlikdagi mexanizm","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Funksiyalar":"Guilloché quyosh siferblati, Sana darchasi","Suvga chidamlilik":"50 metr / 5 BAR","Komplektatsiya":"Original hashamatli Tissot qutisi, hujjatlar, xalqaro kafolat taloni","Kafolat":"2 yil xalqaro rasmiy kafolat","Valyuta narxi":"$350"}'::jsonb) ON CONFLICT (id) DO NOTHING;
