INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('19d64169-840c-25b0-af69-2864afe642b7', 'Tissot Le Locle Powermatic 80 Black Dial 🇨🇭', 'tissot-le-locle-powermatic-80-black-dial', 'Original Shveytsariya brendi Tissot''dan jahonga mashhur Le Locle Powermatic 80 modeli — Shveytsariya soatsozligining beshigi sharafiga nomlangan klassika timsoli. 80 soatlik ulkan quvvat zaxirasiga ega avtomatik mexanizm (Powermatic 80). ''Clous de Paris'' naqshli hashamatli qora siferblat, Rim raqamlari, bargsimon nafis strelkalar va sana darchasi. Qirilishdan himoyalangan sapfir kristall shisha (Sapphire Crystal), 316L zanglamas po''lat korpus, naqshinkor orqa qopqoq va tabiiy qora charm tasma. 2 yil xalqaro rasmiy kafolat bilan. Narxi: $650.', 8320000, 9500000, 12, '5d0c6b4d-072b-e8cc-e434-809c655695be', 'Tissot', 4, 'TIS-LE-LOCLE-PM80-BLK', 5, 16, '/products/tissot_le_locle_powermatic_80_black.png', true, false, true, '{"Ishlab chiqaruvchi davlat":"Shveytsariya (Swiss Made 🇨🇭)","Korpus o''lchami":"39.5 mm","Korpus materiali":"316L zanglamas tibbiy po''lat (Solid Stainless Steel)","Mexanizm":"Swiss Powermatic 80.111 Avtomatik (80 soat quvvat zaxirasi)","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Tasma":"Tabiiy qora charm (Alligator naqshli, Tissot kapalak qisqich)","Funksiyalar":"Clous de Paris naqshli siferblat, Rim raqamlari, Sana, Gravirovka qilingan orqa qopqoq","Suvga chidamlilik":"30 metr / 3 BAR","Komplektatsiya":"Original hashamatli Tissot qutisi, hujjatlar, xalqaro kafolat taloni","Kafolat":"2 yil xalqaro rasmiy kafolat","Valyuta narxi":"$650"}'::jsonb) ON CONFLICT (id) DO NOTHING;
