INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('552c1239-4e7c-6c0e-33f8-7985d1e2e798', 'Tissot PRX Powermatic 80 Ice Blue 40mm 🇨🇭', 'tissot-prx-powermatic-80-ice-blue-40mm', 'Dunyo bo''ylab eng mashhur va eng talabgir Shveytsariya soati — Tissot PRX Powermatic 80 Ice Blue (Muzdek moviy vafli naqshli siferblat). 1978-yilgi afsonaviy retro dizayn, integratsiyalashgan qirrali zanglamas po''lat braslet va korpus. 80 soat quvvat zaxirasiga ega Shveytsariya avtomatik mexanizmi (Powermatic 80) va antimagnit Nivachron prujinasi. Tirnalishga chidamli sapfir kristall shisha (Sapphire Crystal), 100 metr (10 ATM) suvga chidamlilik, shaffof orqa qopqoq va sana darchasi. To''plamda: original hashamatli Tissot qutisi, hujjatlar va 2 yil xalqaro rasmiy kafolat bilan. Narxi: $650.', 8320000, 9500000, 12, '5d0c6b4d-072b-e8cc-e434-809c655695be', 'Tissot', 5, 'TIS-PRX-PM80-ICEBLU', 5, 24, '/products/tissot_prx_powermatic_80_ice_blue.png', true, false, true, '{"Ishlab chiqaruvchi davlat":"Shveytsariya (Swiss Made 🇨🇭)","Korpus o''lchami":"40 mm","Korpus va braslet":"316L zanglamas po''lat (Integratsiyalashgan PRX braslet)","Mexanizm":"Swiss Powermatic 80.111 Avtomatik (80 soat quvvat zaxirasi)","Xususiyat":"Muzdek moviy vafli (Waffle) siferblat, Nivachron antimagnit prujina","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Suvga chidamlilik":"10 ATM / 100 metr (Suzishga yaroqli)","Komplektatsiya":"Original hashamatli Tissot qutisi, hujjatlar, xalqaro kafolat taloni","Kafolat":"2 yil xalqaro rasmiy kafolat","Valyuta narxi":"$650"}'::jsonb) ON CONFLICT (id) DO NOTHING;
