INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('ea5641eb-28cb-7ef4-1005-29791320eba6', 'Tissot PRX Powermatic 80 Forged Carbon 40mm 🇨🇭', 'tissot-prx-powermatic-80-forged-carbon-40mm', 'Original Shveytsariya brendi Tissot''dan eng so''nggi innovatsion asar — Tissot PRX Powermatic 80 Forged Carbon. O''ta yengil va mustahkam Forged Carbon (presslangan uglerod tolasi) korpus va siferblat — har bir nusxasi takrorlanmas marmarsimon naqshga ega. 80 soat quvvat zaxirali Shveytsariya avtomatik Powermatic 80 mexanizmi va kremniyli antimagnit spiral. Qirilmaydigan sapfir kristall shisha, qora teksturali silikon/kauchuk tasma, 100 metr (10 ATM) suvga chidamlilik. To''plamda: original hashamatli Tissot qutisi, hujjatlar va 2 yil xalqaro rasmiy kafolat bilan. Narxi: $900.', 11500000, 13000000, 12, '5d0c6b4d-072b-e8cc-e434-809c655695be', 'Tissot', 3, 'TIS-PRX-PM80-CARBON', 5, 19, '/products/tissot_prx_powermatic_80_forged_carbon.png', true, false, true, '{"Ishlab chiqaruvchi davlat":"Shveytsariya (Swiss Made 🇨🇭)","Korpus o''lchami":"40 mm","Korpus va siferblat materiali":"Forged Carbon (Innovatsion presslangan uglerod tolasi)","Mexanizm":"Swiss Powermatic 80.111 Avtomatik (80 soat quvvat zaxirasi)","Tasma":"Yuqori sifatli qora teksturali kauchuk (Rubber strap)","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi, antirefleks)","Suvga chidamlilik":"10 ATM / 100 metr","Komplektatsiya":"Original hashamatli Tissot qutisi, hujjatlar, xalqaro kafolat taloni","Kafolat":"2 yil xalqaro rasmiy kafolat","Valyuta narxi":"$900"}'::jsonb) ON CONFLICT (id) DO NOTHING;
