INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('86ec329b-e3ea-b7c3-ca4d-2da0b147e934', 'Tissot PRX 40mm Blue Dial Quartz 🇨🇭', 'tissot-prx-40mm-blue-dial-quartz', 'Original Shveytsariya brendi Tissot''dan eng mashhur retro-klassika — Tissot PRX 40mm Blue Dial Quartz. 1978-yilgi afsonaviy dizayn, quyosh nurlari taratuvchi sunburst to''q ko''k siferblat, satirlangan 316L zanglamas po''latdan ishlangan integratsiyalashgan qirrali braslet. Tirnalishdan to''liq himoyalangan sapfir kristall shisha (Sapphire Crystal), Shveytsariya ETA kvars mexanizmi (batareya tugash indikatori — EOL bilan), 100 metr (10 ATM) suvga chidamlilik va soat 3 da sana darchasi. To''plamda: original hashamatli Tissot qutisi, xalqaro kafolat kartasi va hujjatlari bilan. Narxi: $400.', 5120000, 5800000, 12, '5d0c6b4d-072b-e8cc-e434-809c655695be', 'Tissot', 5, 'TIS-PRX-40-BLU-QZ', 5, 21, '/products/tissot_prx_40mm_blue_dial_quartz.jpg', true, false, true, '{"Ishlab chiqaruvchi davlat":"Shveytsariya (Swiss Made 🇨🇭)","Model":"Tissot PRX Quartz (T137.410.11.041.00)","Korpus o''lchami":"40 mm (Qalinligi: 10.4 mm)","Korpus va braslet":"316L zanglamas po''lat (Integratsiyalashgan yassi PRX braslet)","Mexanizm":"Swiss Made ETA F06.115 Kvars (EOL funksiyasi bilan)","Siferblat":"To''q ko''k quyosh nuri (Blue Sunburst) siferblat","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Suvga chidamlilik":"10 ATM / 100 metr (Suzishga yaroqli)","Komplektatsiya":"Original Tissot qutisi, hujjatlar, 2 yillik xalqaro kafolat kartasi, qo''shimcha zvenolar","Kafolat":"2 yil xalqaro rasmiy kafolat","Valyuta narxi":"$400"}'::jsonb) ON CONFLICT (id) DO NOTHING;
