INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('dc1fccfa-dec2-d804-f6c5-3b2e2d309625', 'Tissot Ballade Fluted Bezel Bi-Color Blue Dial Sapphire 40mm 🇨🇭', 'tissot-ballade-fluted-bezel-bicolor-blue-dial-sapphire-40mm', 'Original Shveytsariya brendi Tissot''dan nufuzli Ballade modeli — ko''zni qamashtiruvchi to''q moviy (Deep Royal Blue) guilloché siferblat. Hashamatli qirrali tilla lyunet (Fluted Bezel), 5 qatorli Jubilee bi-color (po''lat & oltin PVD) braslet va oltin indekslar. Qirilmaydigan sapfir kristall shisha (Sapphire Crystal), soat 3 da sana darchasi. 40 mm mukammal korpus. Komplektda: original Tissot qutisi, hujjatlar va 2 yil xalqaro rasmiy kafolat bilan. Narxi: $350.', 4480000, 5100000, 12, '5d0c6b4d-072b-e8cc-e434-809c655695be', 'Tissot', 5, 'TIS-BALLADE-FLUTED-BLU', 5, 17, '/products/tissot_ballade_fluted_bezel_blue.png', true, false, true, '{"Ishlab chiqaruvchi davlat":"Shveytsariya (Swiss Made 🇨🇭)","Korpus o''lchami":"40 mm","Bezel (Lyunet)":"Qirrali oltin lyunet (Fluted Bezel — nufuzli dizayn)","Korpus va braslet":"316L zanglamas po''lat va sariq oltin PVD (Jubilee bi-color)","Mexanizm":"Swiss Made ETA Yuqori aniqlikdagi mexanizm","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi)","Funksiyalar":"To''q moviy Guilloché siferblat, Sana darchasi","Suvga chidamlilik":"50 metr / 5 BAR","Komplektatsiya":"Original hashamatli Tissot qutisi, hujjatlar, xalqaro kafolat taloni","Kafolat":"2 yil xalqaro rasmiy kafolat","Valyuta narxi":"$350"}'::jsonb) ON CONFLICT (id) DO NOTHING;
