INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('5c563142-3315-53d2-afb8-0172ee8fd6db', 'Orient Sport Classic Day-Date Black Dial (FUG1X004B)', 'orient-sport-classic-day-date-black-dial', 'Original Yaponiya brendi Orient''dan zamonaviy Sport Classic Day-Date modeli (FUG1X004B). Hashamatli qora siferblat, qulay o''qiluvchi 12 va 6 arab raqamlari, soat 3 da hafta kuni va sana darchasi. Zanglamas po''lat 316L korpus, qorong''uda nur sochuvchi lyuminestsent ko''rsatkichlar va tabiiy qora charm tasma. 50 metr (5 ATM) suvga chidamlilik va yuqori aniqlikdagi yapon kvars mexanizmi. Original qutisi, hujjatlari va 2 yil rasmiy kafolat bilan.', 2550000, 2950000, 14, '84d75ece-80cd-79e1-e6d8-058603151218', 'Orient', 6, 'ORT-SPORT-DD-FUG1X', 5, 10, '/products/orient_sport_classic_day_date_black.jpg', true, false, true, '{"Ishlab chiqaruvchi":"Yaponiya (Original Orient)","Model kodi":"Orient FUG1X004B Sport Classic","Korpus o''lchami":"43 mm (Qalinligi: 9 mm)","Korpus materiali":"Zanglamas po''lat 316L (Solid Stainless Steel)","Mexanizm":"Yapon Orient Yuqori aniqlikdagi kvars mexanizmi","Shisha turi":"Mustahkamlangan mineral kristall shisha","Tasma":"Tabiiy qora charm (Alligator naqshli)","Funksiyalar":"Hafta kuni (Day) va sana (Date), Lyuminestsent strelkalar","Suvga chidamlilik":"50 metr / 5 BAR","Komplektatsiya":"Original Orient qutisi, hujjatlar, kafolat taloni","Kafolat":"2 yil rasmiy kafolat"}'::jsonb) ON CONFLICT (id) DO NOTHING;
