INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('c7e9bdc1-98fd-9a23-6f09-65b1dd8dd4da', 'Tsar Bomba TB8228 Carbon Fiber Skeleton Automatic', 'tsar-bomba-tb8228-carbon-fiber-skeleton-automatic', 'Original Tsar Bomba TB8228 — Richard Mille uslubidagi hashamatli Tonneau shaklidagi karbon korpusli skelet soat. Haqiqiy presslangan uglerod tolasi (Carbon Fiber / Damascus Carbon) korpus, ochiq mexanizm yurishi (Full Skeleton Automatic) va 21 toshli yapon avtomatik mexanizmi. Tirnalishga chidamli gumbazsimon sapfir kristall shisha (Sapphire Crystal), ergonomik ftor-kauchuk (FKM) tasma va 50 metr (5 ATM) suvga chidamlilik. To''plamda: original hashamatli Tsar Bomba qutisi, hujjatlar va 2 yil rasmiy kafolat bilan. Narxi: $400.', 5120000, 5900000, 13, '118dee4b-db4d-e74d-7eeb-2264e986b373', 'Tsar Bomba', 3, 'TSAR-BOMBA-TB8228-CRB', 5, 15, '/products/tsar_bomba_tb8228_carbon_skeleton.jpg', true, false, true, '{"Ishlab chiqaruvchi brend":"Tsar Bomba (Original)","Model":"Tsar Bomba TB8228 Carbon Edition","Korpus shakli va o''lchami":"Tonneau (Bochkasimon) 43.5 x 50.5 mm","Korpus materiali":"Carbon Fiber (Haqiqiy presslangan uglerod tolasi)","Mexanizm":"Yapon 21 Jewels Avtomatik mexanizm (Skeleton)","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi, antirefleks)","Tasma":"Yuqori elastiklikdagi gipoallergen FKM ftor-kauchuk","Xususiyat":"To''liq ochiq skelet siferblat, titan vintlar, lyuminestsent strelkalar","Suvga chidamlilik":"50 metr / 5 BAR","Komplektatsiya":"Original hashamatli Tsar Bomba qutisi, hujjatlar, xalqaro kafolat taloni","Kafolat":"2 yil rasmiy kafolat","Valyuta narxi":"$400"}'::jsonb) ON CONFLICT (id) DO NOTHING;
