INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('f287addf-357d-120a-6cfc-9f1f426933af', 'Tsar Bomba TB8208 Luxury Skeleton Automatic', 'tsar-bomba-tb8208-luxury-skeleton-automatic', 'Original Tsar Bomba TB8208 — Richard Mille uslubidagi hashamatli Tonneau shaklidagi ochiq skelet mexanizmli avtomatik soat. 316L zanglamas po''lat, titan va Rose Gold / Black PVD qoplamali qirrali bezel. 21 toshli yapon avtomatik mexanizmi, qirilmaydigan sapfir kristall shisha (Sapphire Crystal) va yuqori sifatli FKM kauchuk tasma. 50 metr (5 ATM) suvga chidamlilik. To''plamda: original hashamatli Tsar Bomba qutisi, hujjatlar va 2 yil rasmiy xalqaro kafolat bilan. Narxi: $400.', 5120000, 5900000, 13, '118dee4b-db4d-e74d-7eeb-2264e986b373', 'Tsar Bomba', 6, 'TSAR-BOMBA-TB8208-AUTO', 5, 18, '/products/tsar_bomba_tb8208_gold.png', true, false, true, '{"Ishlab chiqaruvchi brend":"Tsar Bomba (Original)","Model":"Tsar Bomba TB8208 Automatic Series","Korpus shakli va o''lchami":"Tonneau (Bochkasimon) 43.5 x 50.5 mm","Korpus va bezel":"316L zanglamas po''lat, Titan va Rose Gold PVD finish","Mexanizm":"Yapon 21 Jewels Avtomatik mexanizm (Full Skeleton)","Shisha turi":"Sapfir kristall (Sapphire Crystal — tirnalmaydi, antirefleks)","Tasma":"Yuqori elastiklikdagi gipoallergen FKM ftor-kauchuk","Xususiyat":"Rose Gold, Titanium va All-Black rang variantlari, titan vintlar","Suvga chidamlilik":"50 metr / 5 BAR","Komplektatsiya":"Original hashamatli Tsar Bomba qutisi, hujjatlar, 2 yillik xalqaro kafolat kartasi","Kafolat":"2 yil rasmiy kafolat","Valyuta narxi":"$400"}'::jsonb) ON CONFLICT (id) DO NOTHING;
