INSERT INTO products (id, name, slug, description, price, old_price, discount, category_id, brand, stock, sku, rating, reviews_count, image, is_active, is_featured, is_new, specifications) VALUES ('5c622a6f-f62e-76e6-aebd-52443b068828', 'Tsar Bomba TB8605 Carbon Fiber ''Dark Matter'' Automatic', 'tsar-bomba-tb8605-carbon-fiber-dark-matter-automatic', 'Original Tsar Bomba TB8605-04 ''Dark Matter'' — eng yuqori toifadagi presslangan uglerod tolasi (Forged Carbon Fiber) korpusga ega bo''lgan premium skelet avtomatik soat. Richard Mille uslubidagi ergonomik tonneau (bochkasimon) dizayn, ochiq oltin tishli mexanik uzatmalar, qirilmaydigan antirefleksli sapfir kristall oyna (Sapphire Crystal) va yuqori sifatli qora FKM ftor-kauchuk tasma. 50 metr (5 ATM) suvga chidamlilik. To''plamda: original kumushrang Tsar Bomba sovg''a qutisi, firma paketi, xalqaro kafolat pasporti va Timeless rasmiy kafolat kartasi bilan. Narxi: $650.', 8320000, 9500000, 12, '118dee4b-db4d-e74d-7eeb-2264e986b373', 'Tsar Bomba', 3, 'TSAR-BOMBA-TB8605-04-DARK', 5, 15, '/products/tsar_bomba_tb8605_dark_matter.jpg', true, false, true, '{"Ishlab chiqaruvchi brend":"Tsar Bomba (Original)","Model":"Tsar Bomba TB8605-04 Dark Matter Series","Korpus shakli va o''lchami":"Ergonomik Tonneau 43.5 x 50.5 mm (Qalinligi: 15.5 mm)","Korpus materiali":"Forged Carbon Fiber (Haqiqiy presslangan uglerod tolasi)","Mexanizm":"Yapon avtomatik mexanizmi (Open Skeleton, Avtopodzavod)","Shisha turi":"Qavariq sapfir kristall (Sapphire Crystal — tirnalmaydi, antirefleks)","Tasma":"Premium toifadagi gipoallergen qora FKM ftor-kauchuk tasma","Xususiyat":"Ochiq skelet mexanika, oltin rangli detallar, engil uglerod korpus","Suvga chidamlilik":"50 metr / 5 BAR","Komplektatsiya":"Original kumushrang Tsar Bomba qutisi, firma paketi, kafolat pasporti, Timeless kartasi","Kafolat":"2 yil rasmiy kafolat","Valyuta narxi":"$650"}'::jsonb) ON CONFLICT (id) DO NOTHING;
